const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function P(m,name,low){m.userData.name=name;m.userData.low=!!low;return m}
const mesh=(g,m)=>new THREE.Mesh(g,m);
function inst(geo,mat,mats){const im=new THREE.InstancedMesh(geo,mat,mats.length);mats.forEach((m,i)=>im.setMatrixAt(i,m));im.instanceMatrix.needsUpdate=true;im.computeBoundingSphere();return im}
const M4=(p,q,s)=>new THREE.Matrix4().compose(p,q||new THREE.Quaternion(),s||V3(1,1,1));
const qFrom=(a,b)=>new THREE.Quaternion().setFromUnitVectors(a.clone().normalize(),b.clone().normalize());
const qRand=R=>new THREE.Quaternion().setFromEuler(new THREE.Euler(R()*6.28,R()*6.28,R()*6.28));
const Y=V3(0,1,0),X=V3(1,0,0);

/* ================= ОРГАНОИДТАР ================= */
function mito(R,cut){const g=new THREE.Group(),L=.45+R()*.3;
 const outer=new THREE.CapsuleGeometry(.2,L,10,24);outer.rotateZ(Math.PI/2);
 g.add(P(mesh(outer,PM({color:0xe4572e,roughness:.2,clearcoat:1,transparent:true,opacity:.45,depthWrite:false,side:THREE.DoubleSide,clippingPlanes:cut})),'Митохондрия'));
 const pl=[];const n=6+Math.floor(R()*3);for(let k=0;k<n;k++){const d=new THREE.CylinderGeometry(.145,.145,.026,22,1);d.rotateZ(Math.PI/2);deform(d,v=>{v.x+=.018*Math.sin(v.y*30+k*2)+.018*Math.sin(v.z*26)});d.translate(-L/2-.05+(L+.1)*(k+.5)/n,(k%2?1:-1)*.035,0);pl.push(plain(d))}
 g.add(P(mesh(mergeG(pl),PM({color:0xf59a5b,roughness:.35,clearcoat:.5,clippingPlanes:cut})),'Митохондрия'));
 const inn=new THREE.CapsuleGeometry(.17,L,8,18);inn.rotateZ(Math.PI/2);g.add(P(mesh(inn,PM({color:0xf7c58e,roughness:.6,transparent:true,opacity:.3,depthWrite:false,clippingPlanes:cut})),'Митохондрия'));return g}
function golgi(R,cut,s=1){const g=new THREE.Group(),m=PM({color:0xe3a33a,roughness:.3,clearcoat:.8,clippingPlanes:cut}),parts=[];
 for(let k=0;k<6;k++){const r=(.62-k*.045)*s;const prof=[V3(0,-.028*s,0),V3(r*.9,-.028*s,0),V3(r,-.012*s,0),V3(r*1.02,0,0),V3(r,.012*s,0),V3(r*.9,.028*s,0),V3(0,.028*s,0)].map(p=>new THREE.Vector2(p.x,p.y));const l=new THREE.LatheGeometry(prof,40);deform(l,v=>{v.y+=.45*(v.x*v.x+v.z*v.z)/s+.03*Math.sin(v.x*20)*s;v.z*=.7});l.translate(0,k*.085*s,0);parts.push(plain(l))}
 g.add(P(mesh(mergeG(parts),m),'Гольджи кешені'));const ves=[];for(let i=0;i<16;i++){const a=R()*6.28,h=R()*.5*s;const v=new THREE.SphereGeometry((.04+R()*.035)*s,10,8);v.translate(Math.cos(a)*.68*s,h+.25*s,Math.sin(a)*.5*s);ves.push(plain(v))}g.add(P(mesh(mergeG(ves),m),'Гольджи кешені'));return g}
function centriole(){const p=[];for(let k=0;k<9;k++){const a=k*Math.PI*2/9;for(let j=0;j<3;j++){const c=new THREE.CylinderGeometry(.02,.02,.36,8);const r=.1+j*.032,tw=a+j*.18;c.translate(Math.cos(tw)*r,0,Math.sin(tw)*r);p.push(plain(c))}}return mergeG(p)}
function roughER(g,c0,R,N,cut,layers=4,r0=1.35,phi=[.35,1],th=[.45,2.4],nRib=1200){const m=PM({color:0x5c6fd1,roughness:.35,clearcoat:.6,side:THREE.DoubleSide,clippingPlanes:cut});const sheets=[],ribs=[];
 for(let k=0;k<layers;k++){const r=r0+k*.16;const s=new THREE.SphereGeometry(r,110,60,Math.PI*phi[0],Math.PI*phi[1],th[0],th[1]-th[0]);deform(s,v=>{const f=1+.05*N(v.x*2.4+k,v.y*2.4,v.z*2.4)+.02*Math.sin(Math.atan2(v.z,v.x)*14);v.multiplyScalar(f)});s.translate(c0.x,c0.y,c0.z);sheets.push(plain(s));
  for(let i=0;i<nRib/layers;i++){const ph=Math.PI*(phi[0]+R()*phi[1]),t=th[0]+R()*(th[1]-th[0]);const d=V3(-Math.cos(ph)*Math.sin(t),Math.cos(t),Math.sin(ph)*Math.sin(t));const p=d.clone().multiplyScalar(r);const f=1+.05*N(p.x*2.4+k,p.y*2.4,p.z*2.4)+.02*Math.sin(Math.atan2(p.z,p.x)*14);const q=d.clone().multiplyScalar(r*f+(R()<.5?.035:-.035)).add(c0);ribs.push(M4(q))}}
 g.add(P(mesh(mergeG(sheets),m),'Түйіршікті ЭПТ'));const rg=new THREE.SphereGeometry(.028,8,6);g.add(P(inst(rg,PM({color:0x2a1b63,roughness:.5}),ribs),'Рибосомалар'))}
function smoothER(g,c,R,cut,n=10){const parts=[];for(let i=0;i<n;i++){let p=c.clone().add(V3((R()-.5)*.8,(R()-.5)*.8,(R()-.5)*.8)),d=V3(R()-.5,R()-.5,R()-.5).normalize();const pts=[];for(let k=0;k<7;k++){pts.push(p.clone());d.add(V3((R()-.5)*1.2,(R()-.5)*1.2,(R()-.5)*1.2)).normalize();p.addScaledVector(d,.22)}parts.push(plain(vtube(pts,40,()=>.045,8)))}g.add(P(mesh(mergeG(parts),PM({color:0x7cc0e8,roughness:.3,clearcoat:.7,clippingPlanes:cut})),'Тегіс ЭПТ'))}

