function chloroGeo(R){const gr=[];for(let s=0;s<6;s++){const x=-.24+s*.096,y=(R()-.5)*.05,z=(R()-.5)*.12;for(let k=0;k<6;k++){const c=new THREE.CylinderGeometry(.045,.045,.012,14);c.translate(x,y-.04+k*.016,z);gr.push(plain(c))}}for(let i=0;i<5;i++){const b=new THREE.BoxGeometry(.5,.004,.03);b.rotateZ((R()-.5)*.3);b.translate(0,(R()-.5)*.06,(R()-.5)*.14);gr.push(plain(b))}return mergeG(gr)}
function buildPlant(g,ctx){const R=rnd(21),N=makeNoise(21),T=tex(),cut=ctx.cut;
 g.add(P(mesh(new RoundedBoxGeometry(6.6,4.4,4.4,8,.6),PM({color:0xa9c97e,roughness:.6,clearcoat:.3,bumpMap:T.muscle,bumpScale:2,clippingPlanes:cut})),'Жасуша қабырғасы',true));
 g.add(P(mesh(new RoundedBoxGeometry(6.15,3.95,3.95,8,.45),PM({color:0xd9e5a8,roughness:.6,side:THREE.BackSide,clippingPlanes:cut})),'Жасуша қабырғасы',true));
 g.add(P(mesh(new RoundedBoxGeometry(6.05,3.85,3.85,8,.42),PM({color:0xf0f3c8,roughness:.7,side:THREE.BackSide,clippingPlanes:cut,bumpMap:T.organ,bumpScale:.6})),'Цитоплазма',true));
 const pds=[];for(let i=0;i<30;i++){const a=R()<.5;const y=(R()-.5)*3.4,z=(R()-.5)*3.4;const c=new THREE.CylinderGeometry(.04,.04,.5,8);c.rotateZ(Math.PI/2);c.translate((a?1:-1)*3.1,y,z);pds.push(plain(c))}g.add(P(mesh(mergeG(pds),PM({color:0x6d8f3f,roughness:.5,clippingPlanes:cut})),'Плазмодесмалар'));
 const vc=V3(-.45,0,-.25);const vg=deform(new THREE.SphereGeometry(1,96,64),v=>{v.multiplyScalar(1+.04*N(v.x*2,v.y*2,v.z*2));v.set(v.x*2.2,v.y*1.42,v.z*1.42)});vg.translate(vc.x,vc.y,vc.z);
 g.add(P(mesh(vg,PM({color:0x8fd0ff,roughness:.05,clearcoat:1,transparent:true,opacity:.38,depthWrite:false,side:THREE.DoubleSide,clippingPlanes:cut})),'Орталық вакуоль'));
 const cg=chloroGeo(R),om=PM({color:0x43a047,roughness:.25,clearcoat:.9,transparent:true,opacity:.55,depthWrite:false,clippingPlanes:cut}),im=PM({color:0x1b5e20,roughness:.4,clippingPlanes:cut});const sh=new THREE.SphereGeometry(1,28,18);sh.scale(.36,.17,.24);sh.scale(1.25,1.25,1.25);cg.scale(1.25,1.25,1.25);
 let k=0,guard=0;while(k<36&&guard<5000){guard++;const p=V3((R()-.5)*5.6,(R()-.5)*3.5,(R()-.5)*3.5);const e=((p.x-vc.x)/2.4)**2+((p.y-vc.y)/1.6)**2+((p.z-vc.z)/1.6)**2;const nearWall=Math.max(Math.abs(p.x)-2.3,Math.abs(p.y)-1.3,Math.abs(p.z)-1.3)>0;if(e<1.05||!nearWall)continue;if(p.distanceTo(V3(2.2,.6,-1.0))<.8)continue;const q=qRand(R);const o=mesh(sh,om),i=mesh(cg,im);o.position.copy(p);i.position.copy(p);o.quaternion.copy(q);i.quaternion.copy(q);g.add(P(o,'Хлоропласт'),P(i,'Хлоропласт'));k++}
 const nc=V3(2.2,.6,-1.0);const ng=deform(new THREE.SphereGeometry(.62,64,48),v=>v.multiplyScalar(1+.04*N(v.x*5,v.y*5,v.z*5)));ng.translate(nc.x,nc.y,nc.z);g.add(P(mesh(ng,PM({color:0x8a5cc4,roughness:.35,clearcoat:.7,bumpMap:T.fine,bumpScale:.8})),'Ядро'));
 const pores=[];for(let i=0;i<70;i++){const n=V3(R()-.5,R()-.5,R()-.5).normalize();pores.push(M4(n.clone().multiplyScalar(.64).add(nc),qFrom(Y,n)))}const pg=new THREE.TorusGeometry(.035,.013,8,12);pg.rotateX(Math.PI/2);g.add(P(inst(pg,PM({color:0x4a2a80}),pores),'Ядро'));
 roughER(g,nc,R,N,cut,3,.8,[.6,.9],[.6,2.2],260);
 const gg=golgi(R,cut,.6);gg.position.set(1.6,-.9,-1.3);gg.rotation.set(.3,.8,0);g.add(gg);
 [[2.4,-1.2,-.9],[-2.4,1.3,1.2],[1.2,1.4,1.5],[-1.8,-1.4,1.3],[2.5,1.2,-1.0],[.4,-1.6,1.5]].forEach(s=>{const m=mito(R,cut);m.position.set(...s);m.scale.setScalar(.8);m.quaternion.copy(qRand(R));g.add(m)});
 const fr=[];for(let i=0;i<160;i++){const p=V3((R()-.5)*5.8,(R()-.5)*3.6,(R()-.5)*3.6);const e=((p.x-vc.x)/2.3)**2+((p.y-vc.y)/1.5)**2+((p.z-vc.z)/1.5)**2;if(e<1.05){i--;continue}fr.push(M4(p))}g.add(P(inst(new THREE.SphereGeometry(.026,8,6),PM({color:0x3a2470}),fr),'Рибосомалар'))}

