 g.add(P(mesh(atr([-.72,1.22,.1],[.62,.55,.6],3),mus(0x7d2233)),'Оң жүрекше'));g.add(P(mesh(atr([.3,1.3,-.55],[.6,.45,.5],4),mus(0x7d2233)),'Сол жүрекше'));
