 const ves=(pts,r,c,n,tw=60)=>g.add(P(mesh(vtube(pts,tw,typeof r==='function'?r:()=>r,20),PM({color:c,roughness:.32,clearcoat:.8,bumpMap:T.fine,bumpScale:.5,clippingPlanes:cut,side:THREE.DoubleSide})),n));
