 [[.45,0,.2],[1.1,2.4,.3],[1.7,4.6,.25],[2.35,1.2,.35]].forEach(([y,a,b],i)=>{const base=stemC.getPointAt(y/3.35);const pet=vtube([base,base.clone().add(V3(Math.cos(a)*.25,.12,Math.sin(a)*.25))],8,()=>.025,6);g.add(P(mesh(pet,PM({color:0x4a8f35,roughness:.5})),'Жапырақ (сағақ)'));
  const lf=leafGeo(1.15-i*.1,.38,{su:28,sv:10,fold:.25,bend:-.9,serr:.06,serrN:60,sk:.6});lf.rotateX(-Math.PI/2+.5);lf.rotateY(-a+Math.PI/2);const tip=base.clone().add(V3(Math.cos(a)*.25,.12,Math.sin(a)*.25));lf.translate(tip.x,tip.y,tip.z);g.add(P(mesh(lf,lm),'Жапырақ (тақта)'))});
 const top=stemC.getPointAt(1);const rec=new THREE.SphereGeometry(.13,24,18);rec.scale(1,.6,1);rec.translate(top.x,top.y,top.z);g.add(P(mesh(rec,PM({color:0x5f9c3a,roughness:.5})),'Гүл табаны'));
 for(let i=0;i<5;i++){const a=i/5*6.28+.3;const s=leafGeo(.3,.1,{cup:.3,bend:.6});s.rotateX(-1.2);s.rotateY(-a+Math.PI/2);s.translate(top.x,top.y-.02,top.z);g.add(P(mesh(s,PM({color:0x4f8c33,roughness:.5,side:THREE.DoubleSide})),'Тостағанша'))}
 for(let i=0;i<5;i++){const a=i/5*6.28;const p=leafGeo(.8,.38,{su:24,sv:12,sk:.45,cup:.35,bend:.4,base:.05});p.rotateX(-1.2);p.rotateY(-a+Math.PI/2);p.translate(top.x,top.y+.03,top.z);g.add(P(mesh(p,pm),'Күлте жапырақшалары'))}
 const st=[];for(let i=0;i<22;i++){const a=i/22*6.28+R()*.2,r=.04+R()*.05,h=.22+R()*.08;const e=V3(top.x+Math.cos(a)*(r+.06),top.y+h,top.z+Math.sin(a)*(r+.06));st.push(plain(cylBetween(V3(top.x+Math.cos(a)*r,top.y+.02,top.z+Math.sin(a)*r),e,.006,5)));const an=new THREE.CapsuleGeometry(.014,.03,4,8);an.rotateZ(Math.PI/2);an.rotateY(-a);an.translate(e.x,e.y,e.z);st.push(plain(an))}
 g.add(P(mesh(mergeG(st),PM({color:0xf9d34a,roughness:.5})),'Аталықтар'));
 const ov=new THREE.SphereGeometry(.05,16,12);ov.scale(1,1.3,1);ov.translate(top.x,top.y+.06,top.z);const sty=plain(cylBetween(V3(top.x,top.y+.08,top.z),V3(top.x,top.y+.34,top.z),.012,8));const stg=new THREE.SphereGeometry(.03,12,8);stg.scale(1.3,.6,1.3);stg.translate(top.x,top.y+.35,top.z);g.add(P(mesh(mergeG([plain(ov),sty,plain(stg)]),PM({color:0x9ccc65,roughness:.45,clearcoat:.5})),'Аналық'));
 const bud=V3(-.05,2.55,0);const bs=stemC.getPointAt(2.2/3.35);g.add(P(mesh(vtube([bs,bud.clone().add(V3(-.3,.1,.05)),bud.clone().add(V3(-.45,.35,.05))],16,()=>.03,8),PM({color:0x3f8a2f})),'Сабақ'));const bd=new THREE.SphereGeometry(.1,20,16);bd.scale(1,1.6,1);bd.translate(-.5,2.98,.05);g.add(P(mesh(bd,PM({color:0x7cb342,roughness:.5,clearcoat:.4,bumpMap:T.fine,bumpScale:.5})),'Гүл бүршігі'));
 const rm=PM({color:0xd9c3a0,roughness:.7,bumpMap:T.bark,bumpScale:.6});function br(p,dir,len,r,dep){const pts=[p.clone()];let d=dir.clone(),q=p.clone();for(let i=0;i<8;i++){d.add(V3((R()-.5)*.45,-.08,(R()-.5)*.45)).normalize();q=q.clone().addScaledVector(d,len/8);pts.push(q)}const tg=vtube(pts,30,u=>r*(1-u*.85),7);g.add(P(mesh(tg,rm),dep?'Жанама тамырлар':'Негізгі тамыр'));const c=tg.userData.curve;if(dep<2)for(let k=0;k<(dep?3:6);k++){const t=.2+k*(dep?.22:.13),bp=c.getPointAt(t),a=R()*6.28;br(bp,V3(Math.cos(a),-.35,Math.sin(a)),len*.45,r*.5,dep+1)}}
 br(V3(0,0,0),V3(0,-1,0),2.1,.08,0);
