function buildLeaf(g){const R=rnd(55),T=tex(),N=makeNoise(55);const nearV=(x,y)=>Math.hypot(x,(y+.18)*1.2)<.62;
 g.add(P(mesh(xform(new THREE.BoxGeometry(4.1,.035,2.5),[0,.8,0]),PM({color:0xfff5c4,roughness:.05,clearcoat:1,transparent:true,opacity:.4,depthWrite:false})),'Кутикула'));
 g.add(P(mesh(xform(new THREE.BoxGeometry(4.1,.035,2.5),[0,-.78,0]),PM({color:0xfff5c4,roughness:.05,clearcoat:1,transparent:true,opacity:.4,depthWrite:false})),'Кутикула'));
 const ep=(y,n)=>{const c=[];for(let i=0;i<10;i++)for(let k=0;k<6;k++){const x=-1.85+i*.41,z=-1.03+k*.41;if(n&&n.some(s=>Math.abs(x-s[0])<.3&&Math.abs(z-s[1])<.3))continue;const b=new RoundedBoxGeometry(.39,.17,.39,2,.05);deform(b,v=>{v.y*=1+.15*N(x*5+v.x,v.z*5,y)});b.translate(x,y,z);c.push(plain(b))}return mergeG(c)};
 const em=PM({color:0xe8f5e0,roughness:.15,clearcoat:.8,transparent:true,opacity:.6,depthWrite:false});
 g.add(P(mesh(ep(.69),em),'Жоғарғы эпидермис'));const stom=[[-1.24,-.21],[.4,.61],[1.22,-.62]];g.add(P(mesh(ep(-.67,stom),em),'Төменгі эпидермис'));
 const pal=[],chl=[];for(let i=0;i<20;i++)for(let k=0;k<12;k++){const x=-1.9+i*.2,z=-1.1+k*.2;const y=.36;if(nearV(x,y-.1))continue;const c=new THREE.CapsuleGeometry(.085,.3,6,12);c.translate(x+(R()-.5)*.02,y,z+(R()-.5)*.02);pal.push(plain(c));for(let j=0;j<7;j++){const a=R()*6.28,h=(R()-.5)*.32;chl.push(M4(V3(x+Math.cos(a)*.075,y+h,z+Math.sin(a)*.075),qFrom(Y,V3(Math.cos(a),0,Math.sin(a))),V3(1,.5,1)))}}
 g.add(P(mesh(mergeG(pal),PM({color:0x9ccc65,roughness:.2,clearcoat:.7,transparent:true,opacity:.55,depthWrite:false})),'Бағаналы (палисадты) мезофилл'));
 const sp=[];let tries=0;const pts=[];while(pts.length<120&&tries<4000){tries++;const p=V3((R()-.5)*3.9,-.08-R()*.45,(R()-.5)*2.35);if(nearV(p.x,p.y))continue;const r=.12+R()*.06;if(pts.some(q=>q.p.distanceTo(p)<q.r+r+.02))continue;pts.push({p,r})}
 pts.forEach(({p,r})=>{const s=deform(new THREE.SphereGeometry(r,16,12),v=>v.multiplyScalar(1+.22*N(v.x*9+p.x,v.y*9,v.z*9+p.z)));s.translate(p.x,p.y,p.z);sp.push(plain(s));for(let j=0;j<3;j++){const d=V3(R()-.5,R()-.5,R()-.5).normalize();chl.push(M4(p.clone().addScaledVector(d,r*.85),qFrom(Y,d),V3(1,.5,1)))}});
 g.add(P(mesh(mergeG(sp),PM({color:0xc5e1a5,roughness:.25,clearcoat:.6,transparent:true,opacity:.6,depthWrite:false})),'Борпылдақ мезофилл'));
 const cg=new THREE.SphereGeometry(.032,10,8);g.add(P(inst(cg,PM({color:0x1b7a2a,roughness:.4,clearcoat:.4}),chl),'Хлоропласттар'));
 const gc=[];stom.forEach(([x,z])=>{[-1,1].forEach(s=>{const t=new THREE.TorusGeometry(.12,.055,12,24,Math.PI);t.rotateX(Math.PI/2);t.rotateY(s>0?0:Math.PI);t.scale(1,.9,1.25);t.translate(x+s*.03,-.67,z);gc.push(plain(t))})});g.add(P(mesh(mergeG(gc),PM({color:0x66bb6a,roughness:.3,clearcoat:.7})),'Лептесік (устьице)'));
 const xy=[],ph=[],bs=[];[[-.2,-.05,.09],[0,-.03,.1],[.2,-.05,.09],[-.1,-.2,.07],[.1,-.2,.07],[0,-.36,.05]].forEach(([x,y,r])=>{const c=new THREE.CylinderGeometry(r,r,2.5,20,1,true);c.rotateX(Math.PI/2);c.translate(x,y,0);xy.push(plain(c));const w=new THREE.TorusGeometry(r,.012,6,20);for(let z=-1.2;z<=1.2;z+=.1){const t=w.clone();t.translate(x,y,z);xy.push(plain(t))}});
 for(let i=0;i<10;i++){const a=Math.PI*.2+i/9*Math.PI*.6,x=Math.cos(a)*.2,y=-.5-Math.sin(a)*.08;const c=new THREE.CylinderGeometry(.04,.04,2.5,10);c.rotateX(Math.PI/2);c.translate(x,y+.04,0);ph.push(plain(c))}
 for(let i=0;i<16;i++){const a=i/16*6.28,x=Math.cos(a)*.5,y=-.25+Math.sin(a)*.42;const c=new THREE.CapsuleGeometry(.07,2.35,4,10);c.rotateX(Math.PI/2);c.translate(x,y,0);bs.push(plain(c))}
 g.add(P(mesh(mergeG(xy),PM({color:0xc0452f,roughness:.35,clearcoat:.6,side:THREE.DoubleSide})),'Ксилема'));g.add(P(mesh(mergeG(ph),PM({color:0x8bc34a,roughness:.4,clearcoat:.4})),'Флоэма'));g.add(P(mesh(mergeG(bs),PM({color:0xd4e8b8,roughness:.3,transparent:true,opacity:.55,depthWrite:false})),'Өткізгіш шоқ қынабы'));
 const box=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(4.1,1.6,2.5)),new THREE.LineBasicMaterial({color:0x9ccc65,transparent:true,opacity:.35}));g.add(box)}

