function clipped(p,o){const cp=o.material&&o.material.clippingPlanes;if(!cp||!cp.length)return false;return o.material.clipIntersection?cp.every(pl=>pl.distanceToPoint(p)<0):cp.some(pl=>pl.distanceToPoint(p)<0)}
